#[derive(Debug)]
struct Pair<T> { a: T, b: T }

impl<T: PartialOrd + Copy> Pair<T> {
    fn max(&self) -> T { if self.a > self.b { self.a } else { self.b } }
}

fn main() {
    let p = Pair { a: 3, b: 7 };
    println!("{}", p.max());          // 7
    // let q = Pair { a: 1, b: 2.0 }; // error[E0308]: mismatched types — both fields share ONE T
}

